        __('Jan'), __('Feb'), __('Mar'), __('Apr'), __('May'), __('Jun'),
        __('Jul'), __('Aug'), __('Sep'), __('Oct'), __('Nov'), __('Dec')
    ];
    
    return `${monthNames[month - 1]}<br><small>${year}</small>`;
